import sys
from pathlib import Path
import random
from glob import glob
sys.path.append(str(Path(__file__).resolve().parents[1]))
from delete_residues import change_residue

M13_standard = ""

def get_random_snippet(sequence, length): # Extract a random snippet of given length from sequence
    start_idx = random.randint(0, len(sequence) - length)
    return sequence[start_idx:start_idx + length]


if __name__ == "__main__": 
    complements = {
    'A' : 'T', 'T' : 'A', 'C' : 'G', 'G' : 'C'
    }
    with open(str(Path(__file__).resolve().parents[1]) + '/Helix_separator/cpptraj_base_pairing.txt', 'r') as f:     # contains lines with resid1-redid2,resid4-resid5,... strand1sequence strand2sequence
        for line in f.readlines():
            base_pairing_info = line.split()[0][:-1] 
            strand1_seq = line.split()[1]
            strand2_seq = line.split()[2]
            
            strand1_resid = [int(pair.split('-')[0]) for pair in base_pairing_info.split(',')]
            strand2_redid = [int(pair.split('-')[1]) for pair in base_pairing_info.split(',')]

            snippet_length = len(strand1_seq)  # Change as needed
            random_snippet = get_random_snippet(M13_standard, snippet_length)
            print(f"Random snippet: {random_snippet}")
            
            pdb_file = glob(str(Path(__file__).resolve().parents[1]) + '/input/*.pdb')[0]
            for i, base in enumerate(random_snippet):
                change_residue(pdb_file, strand1_resid[i], base)
                change_residue(pdb_file, strand2_redid[i], complements[base])




